<script setup lang="ts">
import { computed, ref, watch, onUnmounted } from 'vue'
import { get, post, requestId, tenantBase } from '../api/client'
import { app, legacyUrl, prepareLegacy } from '../app'
import DocumentText from '../components/DocumentText.vue'
type Session={id:number;title:string;archived_at?:string;ticket?:{key:string;title:string}}
type Message={id:number;role:string;body:string;data?:{kind?:string;state?:string;step?:number;trace?:{operation:string;status:string;arguments:unknown;result:unknown}[];run?:number}}
type Result={message:Message;pending:boolean;step:number}
const props=defineProps<{pkey:string}>()
const sessions=ref<Session[]>([]),session=ref<Session|null>(null),messages=ref<Message[]>([]),draft=ref(''),error=ref(''),busy=ref(false),stopping=ref(false),loading=ref(false)
const working=computed(()=>messages.value.find(m=>m.data?.kind==='assistant'&&m.data.state==='working'))
let generation=0
const storageKey=()=>`${tenantBase()}:${app.meta?.access?.user||app.meta?.user}:assistant:${props.pkey}`
const pendingKey=(id:number)=>`${storageKey()}:pending:${id}`
async function list(){const n=generation;const result=await get<{sessions:Session[]}>(`/api/projects/${encodeURIComponent(props.pkey)}/sessions`);if(n===generation)sessions.value=result.sessions}
async function read(id:number){const n=generation;const result=await get<{session:Session;messages:Message[]}>(`/api/sessions/${id}`);if(n===generation){session.value=result.session;messages.value=result.messages}}
async function choose(id:number){if(busy.value)return;const n=++generation;error.value='';loading.value=true;session.value=null;messages.value=[];draft.value='';try{await read(id);if(n===generation){localStorage.setItem(storageKey(),String(id));const pending=localStorage.getItem(pendingKey(id));if(pending)draft.value=JSON.parse(pending).question}}catch(e){if(n===generation)error.value=String(e)}finally{if(n===generation)loading.value=false}}
function fresh(){if(busy.value)return;generation++;session.value=null;messages.value=[];draft.value='';error.value='';localStorage.removeItem(storageKey())}
function update(r:Result){const i=messages.value.findIndex(m=>m.id===r.message.id);if(i<0)messages.value.push(r.message);else messages.value[i]=r.message}
async function drive(id:number,result:Result,n:number){let r=result;while(r.pending&&!stopping.value&&n===generation){r=await post<Result>(`/api/sessions/${id}/assistant`,{message:r.message.id,step:r.step});if(n===generation)update(r)}if(stopping.value&&r.pending&&n===generation){r=await post<Result>(`/api/sessions/${id}/assistant`,{message:r.message.id,action:'stop'});if(n===generation)update(r)}}
async function send(){const question=draft.value.trim();if(!question||busy.value||working.value)return;const n=generation;busy.value=true;stopping.value=false;error.value='';try{if(!session.value){const created=await post<Session>(`/api/projects/${encodeURIComponent(props.pkey)}/sessions`,{kind:'consult',title:question});if(n!==generation)return;session.value=created;localStorage.setItem(storageKey(),String(created.id))}const id=session.value.id,key=pendingKey(id);let pending=JSON.parse(localStorage.getItem(key)||'null');if(pending&&pending.question!==question)throw new Error('上次请求结果待核对，请恢复原问题后重试，避免重复执行。');pending ||= {question,request_id:requestId()};localStorage.setItem(key,JSON.stringify(pending));const result=await post<Result>(`/api/sessions/${id}/assistant`,pending);localStorage.removeItem(key);if(n!==generation)return;draft.value='';await read(id);if(n!==generation)return;update(result);await drive(id,result,n);if(n===generation)await list()}catch(e){if(n===generation)error.value=String(e)}finally{if(n===generation){busy.value=false;stopping.value=false}}}
async function resume(){if(!session.value||!working.value||busy.value)return;const n=generation;busy.value=true;stopping.value=false;error.value='';try{await drive(session.value.id,{message:working.value,pending:true,step:working.value.data?.step||0},n);if(n===generation)await read(session.value.id)}catch(e){if(n===generation)error.value=String(e)}finally{if(n===generation){busy.value=false;stopping.value=false}}}
async function stop(){if(busy.value){stopping.value=true;return}if(!working.value||!session.value)return;const n=generation;busy.value=true;error.value='';try{const r=await post<Result>(`/api/sessions/${session.value.id}/assistant`,{message:working.value.id,action:'stop'});if(n===generation)update(r)}catch(e){if(n===generation)error.value=String(e)}finally{if(n===generation)busy.value=false}}
async function archive(){if(!session.value||busy.value||working.value)return;const n=generation;busy.value=true;error.value='';try{const updated=await post<Session>(`/api/sessions/${session.value.id}`,{archived:!session.value.archived_at});if(n===generation){session.value=updated;await list()}}catch(e){if(n===generation)error.value=String(e)}finally{if(n===generation)busy.value=false}}
watch(()=>props.pkey,async()=>{const n=++generation;session.value=null;messages.value=[];sessions.value=[];draft.value='';error.value='';busy.value=false;stopping.value=false;loading.value=true;try{await list();if(n!==generation)return;const saved=Number(localStorage.getItem(storageKey()));if(saved&&sessions.value.some(s=>s.id===saved)){await read(saved);const pending=localStorage.getItem(pendingKey(saved));if(n===generation&&pending)draft.value=JSON.parse(pending).question}}catch(e){if(n===generation)error.value=String(e)}finally{if(n===generation)loading.value=false}},{immediate:true})
onUnmounted(()=>generation++)
</script>
<template><header class="assistant-heading"><h1>AI 助手</h1><button class="btn" :disabled="busy||loading" @click="fresh">新对话</button></header><p v-if="error" class="error" role="alert">{{error}}</p><div class="assistant-layout"><aside><label class="field">历史对话<select :value="session?.id||''" :disabled="busy||loading" @change="choose(Number(($event.target as HTMLSelectElement).value))"><option disabled value="">选择历史对话</option><option v-for="item in sessions" :key="item.id" :value="item.id">{{item.title}}{{item.archived_at?'（已归档）':''}}</option></select></label><button v-if="session" class="btn" :disabled="busy||!!working" @click="archive">{{session.archived_at?'恢复对话':'归档对话'}}</button><p v-if="session?.ticket"><a :href="legacyUrl('/t/'+encodeURIComponent(session.ticket.key))" @click="prepareLegacy(pkey)">{{session.ticket.key}} · {{session.ticket.title}}</a></p></aside><section class="conversation panel"><h2>{{session?.title||'接下来，想做什么？'}}</h2><p v-if="loading" role="status">正在读取对话…</p><div v-if="!messages.length&&!loading" class="suggestions"><button v-for="q in ['看看这个项目有哪些待办','帮我整理多项需求的依赖','查找相关项目知识']" :key="q" class="btn" @click="draft=q">{{q}}</button></div><article v-for="message in messages" :key="message.id" class="message" :class="{question:message.role==='user'}"><strong>{{message.role==='user'?'我':'Webuddy'}}</strong><DocumentText :text="message.body"/><details v-if="message.data?.trace?.length"><summary>{{message.data.trace.length}} 项操作记录</summary><div v-for="(step,i) in message.data.trace" :key="i"><strong>{{step.operation}} · {{step.status}}</strong><pre>{{JSON.stringify({arguments:step.arguments,result:step.result},null,2)}}</pre></div></details><a v-if="message.data?.run" :href="legacyUrl('/runs')" @click="prepareLegacy(pkey)">运行 #{{message.data.run}}</a></article><div v-if="working" class="run-controls"><span role="status">{{stopping?'正在停止继续处理…':busy?'正在处理…':'处理尚未完成'}}</span><button v-if="!busy" class="btn" @click="resume">继续处理</button><button class="btn" :disabled="stopping" @click="stop">停止继续处理</button></div><form @submit.prevent="send"><label class="field">消息<textarea v-model="draft" :disabled="busy||loading||!!session?.archived_at" rows="4" placeholder="查进度、整理需求，或说明要执行的任务" /></label><button class="btn btn-primary" :disabled="busy||loading||!!working||!draft.trim()||!!session?.archived_at">发送</button></form></section></div></template>
<style scoped>.assistant-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.assistant-heading h1{margin:0}.assistant-layout{display:grid;grid-template-columns:210px minmax(0,1fr);gap:24px}.conversation h2{margin-top:0}.suggestions{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}.message{padding:18px 0;border-bottom:1px solid var(--line)}.message.question{background:var(--bg);padding:16px;border-radius:6px}.message pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.message :deep(.document){padding:8px 0}.run-controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}.conversation form{margin-top:24px}@media(max-width:900px){.assistant-layout{grid-template-columns:1fr}.assistant-layout aside{display:flex;align-items:start;gap:12px;flex-wrap:wrap}.assistant-layout aside .field{flex:1;min-width:180px}}</style>
